describe("doctests of sympy.matrices.repmatrix", () => {
  it("M.col_swap(0, 1)", () => {
    const v1 = MutableDenseMatrix.from(Matrix.of([[rational(0), rational(1)], [rational(0), rational(1)]]));
    v1.colSwap(0, 1);
    expect(sympyStr(v1.colSwap(0, 1))).toBe('None');
  });
  it("M.row_swap(0, 1)", () => {
    const v1 = MutableDenseMatrix.from(Matrix.of([[rational(1), rational(0)], [rational(0), rational(1)]]));
    v1.rowSwap(0, 1);
    expect(sympyStr(v1.rowSwap(0, 1))).toBe('None');
  });
  it("a.T", () => {
    expect(sympyStr(new MutableSparseMatrix(2, 2, [[rational(1), rational(2)], [rational(3), rational(4)]]).T)).toBe('Matrix([[1, 3], [2, 4]])');
  });
  it("A == B", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("A.equals(B)", () => {
    const x = new Sym('x');
    expect(sympyStr(Matrix.of([[mul(x, add(-1, x))], [rational(0)]]).equals(Matrix.of([[mul(x, add(-1, x))], [rational(0)]])))).toBe('True');
  });
  // the arguments do not type-check against the public API
  //   A.equals(2)
  //   => False
  it.todo("A.equals(2)");
  it("A.inv_mod(5)", () => {
    expect(sympyStr(invMod(Matrix.of([[rational(1), rational(2)], [rational(3), rational(4)]]), 5n))).toBe('Matrix([[3, 1], [4, 2]])');
  });
  it("A.inv_mod(3)", () => {
    expect(sympyStr(invMod(Matrix.of([[rational(1), rational(2)], [rational(3), rational(4)]]), 3n))).toBe('Matrix([[1, 1], [0, 1]])');
  });
  it("M.lll()", () => {
    expect(sympyStr(lll(Matrix.of([[rational(1), rational(0), rational(0), rational(0), rational(-20160)], [rational(0), rational(1), rational(0), rational(0), rational(33768)], [rational(0), rational(0), rational(1), rational(0), rational(39578)], [rational(0), rational(0), rational(0), rational(1), rational(47757)]])))).toBe('Matrix([[10, -3, -2, 8, -4], [3, -9, 8, 1, -11], [-3, 13, -9, -3, -9], [-12, -7, -11, 9, -1]])');
  });
  it("T * M == B", () => {
    expect(sympyStr(Matrix.of([[rational(10), rational(-3), rational(-2), rational(8), rational(-4)], [rational(3), rational(-9), rational(8), rational(1), rational(-11)], [rational(-3), rational(13), rational(-9), rational(-3), rational(-9)], [rational(-12), rational(-7), rational(-11), rational(9), rational(-1)]]).equals(Matrix.of([[rational(10), rational(-3), rational(-2), rational(8), rational(-4)], [rational(3), rational(-9), rational(8), rational(1), rational(-11)], [rational(-3), rational(13), rational(-9), rational(-3), rational(-9)], [rational(-12), rational(-7), rational(-11), rational(9), rational(-1)]])))).toBe('True');
  });
  it("M.to_DM()", () => {
    expect(sympyStr(toDM(Matrix.of([[rational(1), rational(2)], [rational(3), rational(4)]]), {}))).toBe('DomainMatrix({0: {0: 1, 1: 2}, 1: {0: 3, 1: 4}}, (2, 2), ZZ)');
  });
  it("M.to_DM().to_Matrix() == M", () => {
    expect(sympyStr(Matrix.of([[rational(1), rational(2)], [rational(3), rational(4)]]).equals(Matrix.of([[rational(1), rational(2)], [rational(3), rational(4)]])))).toBe('True');
  });
  it("M.to_DM().domain", () => {
    const x = new Sym('x');
    expect(sympyStr(ZZ.polyRing(x))).toBe('ZZ[x]');
  });
  it("M.to_DM(field=True).domain", () => {
    const x = new Sym('x');
    expect(sympyStr(ZZ.fracField(x))).toBe('ZZ(x)');
  });
  it("M.to_DM(domain=QQ[x]).domain", () => {
    const x = new Sym('x');
    expect(sympyStr(QQ.polyRing(x))).toBe('QQ[x]');
  });
  it("m[1, 0]", () => {
    expect(sympyStr(Matrix.of([[rational(1), add(2, I)], [rational(3), rational(4)]]).get(1, 0))).toBe('3');
  });
  it("m[:, 0]", () => {
    expect(sympyStr(Matrix.of([[rational(1), add(2, I)], [rational(3), rational(4)]]).extract([0, 1], [0]))).toBe('Matrix([[1], [3]])');
  });
  it("m[0]", () => {
    expect(sympyStr(Matrix.of([[rational(1), add(2, I)], [rational(3), rational(4)]]).get(0, 0))).toBe('1');
  });
  it("m", () => {
    expect(sympyStr(Matrix.of([[rational(1), add(2, I)], [rational(3), rational(4)]]))).toBe('Matrix([[1, 2 + I], [3, 4]])');
  });
  it("M", () => {
    expect(sympyStr(Matrix.of([[rational(1), rational(0)], [rational(1), rational(0)]]))).toBe('Matrix([[1, 0], [1, 0]])');
  });
  it("M (2)", () => {
    expect(sympyStr(Matrix.of([[rational(0), rational(1)], [rational(1), rational(0)]]))).toBe('Matrix([[0, 1], [1, 0]])');
  });
  it("a", () => {
    expect(sympyStr(new MutableSparseMatrix([[1, 2], [3, 4]]))).toBe('Matrix([[1, 2], [3, 4]])');
  });
  it("B", () => {
    expect(sympyStr(at(lllTransform(Matrix.of([[rational(1), rational(0), rational(0), rational(0), rational(-20160)], [rational(0), rational(1), rational(0), rational(0), rational(33768)], [rational(0), rational(0), rational(1), rational(0), rational(39578)], [rational(0), rational(0), rational(0), rational(1), rational(47757)]])), 0))).toBe('Matrix([[10, -3, -2, 8, -4], [3, -9, 8, 1, -11], [-3, 13, -9, -3, -9], [-12, -7, -11, 9, -1]])');
  });
  it("T", () => {
    expect(sympyStr(at(lllTransform(Matrix.of([[rational(1), rational(0), rational(0), rational(0), rational(-20160)], [rational(0), rational(1), rational(0), rational(0), rational(33768)], [rational(0), rational(0), rational(1), rational(0), rational(39578)], [rational(0), rational(0), rational(0), rational(1), rational(47757)]])), 1))).toBe('Matrix([[10, -3, -2, 8], [3, -9, 8, 1], [-3, 13, -9, -3], [-12, -7, -11, 9]])');
  });
  it("M (3)", () => {
    const x = new Sym('x');
    expect(sympyStr(Matrix.of([[x, rational(1)], [rational(1), x]]))).toBe('Matrix([[x, 1], [1, x]])');
  });
});

